SET NAMES utf8mb4;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE,email VARCHAR(190) UNIQUE,phone VARCHAR(30) UNIQUE,password_hash VARCHAR(255) NOT NULL,referral_code VARCHAR(32) UNIQUE,vip_level VARCHAR(20) DEFAULT 'VIP0',status ENUM('active','blocked') DEFAULT 'active',created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE,password_hash VARCHAR(255),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,full_name VARCHAR(100),created_at DATETIME,updated_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_bank_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,bank_name VARCHAR(60),account_number VARCHAR(40),account_holder VARCHAR(100),created_at DATETIME,updated_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_pins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE,pin_hash VARCHAR(255),created_at DATETIME,updated_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE pin_reset_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,status VARCHAR(20),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE balance_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE,main_balance DECIMAL(18,2) DEFAULT 0,bonus_balance DECIMAL(18,2) DEFAULT 0,profit_balance DECIMAL(18,2) DEFAULT 0,commission_balance DECIMAL(18,2) DEFAULT 0,locked_balance DECIMAL(18,2) DEFAULT 0,total_profit DECIMAL(18,2) DEFAULT 0,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ledger_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,type VARCHAR(50),amount DECIMAL(18,2),balance_type VARCHAR(30),reference_type VARCHAR(30),reference_id BIGINT,idempotency_key VARCHAR(191) UNIQUE,status VARCHAR(20),metadata JSON,created_at DATETIME,INDEX(user_id),INDEX(type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE site_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(120) UNIQUE,setting_value TEXT,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE promo_counters (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,counter_key VARCHAR(100) UNIQUE,counter_value BIGINT DEFAULT 0,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE welcome_popup_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,is_active TINYINT(1),display_mode VARCHAR(30),title VARCHAR(120),description TEXT,whatsapp_link VARCHAR(255),image_path VARCHAR(255),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE banners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120),image_path VARCHAR(255),sort_order INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,title VARCHAR(120),body TEXT,is_read TINYINT(1) DEFAULT 0,created_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE information_pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category VARCHAR(80),title VARCHAR(120),content LONGTEXT,is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE app_download_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,file_label VARCHAR(100),file_url VARCHAR(255),is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE promos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120),description TEXT,image_path VARCHAR(255),starts_at DATETIME,ends_at DATETIME,is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE chat_threads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,status VARCHAR(20),created_at DATETIME,updated_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE chat_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,thread_id BIGINT UNSIGNED,sender_type VARCHAR(20),message TEXT,file_path VARCHAR(255),is_read TINYINT(1),created_at DATETIME,INDEX(thread_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vip_levels (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30),min_topup DECIMAL(18,2),min_withdraw DECIMAL(18,2),admin_fee_percent DECIMAL(5,2),access_voucher TINYINT(1),access_game TINYINT(1),is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_vip_status (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE,vip_level_id BIGINT UNSIGNED,total_approved_topup DECIMAL(18,2) DEFAULT 0,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vouchers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) UNIQUE,vip_level_id BIGINT UNSIGNED,voucher_type VARCHAR(40),value DECIMAL(18,2),is_active TINYINT(1),starts_at DATETIME,ends_at DATETIME,quota INT,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE voucher_usages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,voucher_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,reference_type VARCHAR(30),reference_id BIGINT,created_at DATETIME,INDEX(voucher_id),INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vip_games (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),vip_level_id BIGINT UNSIGNED,is_active TINYINT(1),settings JSON,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vip_game_rewards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,game_id BIGINT UNSIGNED,reward_amount DECIMAL(18,2),chance_percent DECIMAL(5,2),created_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vip_game_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,game_id BIGINT UNSIGNED,status VARCHAR(20),started_at DATETIME,ended_at DATETIME,created_at DATETIME,INDEX(user_id),INDEX(game_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vip_game_plays (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,reward_amount DECIMAL(18,2),status VARCHAR(20),created_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE daily_bonus_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE daily_bonus_rewards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,day_number INT,reward_amount DECIMAL(18,2),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE daily_bonus_claims (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,day_number INT,reward_amount DECIMAL(18,2),claimed_date DATE,created_at DATETIME,UNIQUE KEY uq_user_day (user_id,day_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED,name VARCHAR(120),price DECIMAL(18,2),stock INT,daily_profit DECIMAL(18,2),duration_days INT,total_income DECIMAL(18,2),roi_percent DECIMAL(8,2),is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,product_id BIGINT UNSIGNED,status VARCHAR(20),active_until DATETIME,last_mined_date DATE,created_at DATETIME,updated_at DATETIME,INDEX(user_id),INDEX(product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_purchases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,product_id BIGINT UNSIGNED,price DECIMAL(18,2),bonus_used DECIMAL(18,2),main_used DECIMAL(18,2),status VARCHAR(20),created_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mining_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,countdown_minutes INT DEFAULT 120,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mining_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_product_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,status VARCHAR(20),starts_at DATETIME,ends_at DATETIME,processed_at DATETIME,idempotency_key VARCHAR(191) UNIQUE,created_at DATETIME,updated_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mining_profit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,user_product_id BIGINT UNSIGNED,amount DECIMAL(18,2),profit_date DATE,created_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE referral_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE referral_commission_rates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,commission_type VARCHAR(30),level_no INT,rate_percent DECIMAL(5,2),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_referrals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,referrer_user_id BIGINT UNSIGNED,level_no INT,created_at DATETIME,INDEX(user_id),INDEX(referrer_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE referral_tree (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ancestor_user_id BIGINT UNSIGNED,descendant_user_id BIGINT UNSIGNED,depth INT,created_at DATETIME,INDEX(ancestor_user_id),INDEX(descendant_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE referral_commissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,earner_user_id BIGINT UNSIGNED,source_user_id BIGINT UNSIGNED,commission_type VARCHAR(30),level_no INT,amount DECIMAL(18,2),reference_id BIGINT,idempotency_key VARCHAR(191) UNIQUE,status VARCHAR(20),created_at DATETIME,INDEX(earner_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE withdrawals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,amount DECIMAL(18,2),fee_amount DECIMAL(18,2),net_amount DECIMAL(18,2),status VARCHAR(20),rejected_reason VARCHAR(255),created_at DATETIME,updated_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cashify_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,base_url VARCHAR(255),api_version VARCHAR(10),qris_id VARCHAR(100),license_key VARCHAR(255),package_ids JSON,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE topups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,provider_transaction_id VARCHAR(120),original_amount DECIMAL(18,2),unique_nominal DECIMAL(18,2),total_amount DECIMAL(18,2),status VARCHAR(20),payment_method_view VARCHAR(50),idempotency_key VARCHAR(191) UNIQUE,created_at DATETIME,updated_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE deposit_display_methods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,method_name VARCHAR(40),is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE deposit_quick_amounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,amount DECIMAL(18,2),sort_order INT,is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE feature_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,feature_key VARCHAR(100) UNIQUE,is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE menu_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,menu_key VARCHAR(100) UNIQUE,is_active TINYINT(1),created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE maintenance_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,is_maintenance TINYINT(1),message TEXT,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_freezes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,is_frozen TINYINT(1),reason VARCHAR(255),created_at DATETIME,updated_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_status_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,status VARCHAR(20),note VARCHAR(255),created_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_type VARCHAR(20),actor_id BIGINT,action VARCHAR(100),payload JSON,created_at DATETIME,INDEX(actor_type,actor_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identity VARCHAR(190),ip_address VARCHAR(45),attempted_at DATETIME,is_success TINYINT(1),INDEX(identity),INDEX(ip_address)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,token VARCHAR(191),expires_at DATETIME,used_at DATETIME,created_at DATETIME,INDEX(user_id),INDEX(token)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cron_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cron_name VARCHAR(100),status VARCHAR(20),message TEXT,run_at DATETIME,INDEX(cron_name),INDEX(run_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
